import React, { useMemo } from "react";
import { useCurrentFrame, useVideoConfig, AbsoluteFill, interpolate } from '../remotionShim';
// Google Fonts Loader
const useFontLoader = (fonts: string[]) => {
  const stableFonts = React.useMemo(() => {
    const unique = [...new Set(fonts.map((f) => f.trim()))].sort();
    return unique;
  }, [fonts.join("|")]);

  React.useEffect(() => {
    const unloaded = stableFonts.filter(
      (font) =>
        !document.querySelector(
          `link[href*="${font.replace(/\s+/g, "+")}"]`
        )
    );

    if (unloaded.length === 0) return;

    const url = `https://fonts.googleapis.com/css2?${unloaded
      .map((font) => `family=${font.replace(/\s+/g, "+")}:wght@400;600;700`)
      .join("&")}&display=swap`;

    const link = document.createElement("link");
    link.rel = "stylesheet";
    link.href = url;

    document.head.appendChild(link);
  }, [stableFonts]);
};



export type Carousel3DProps = Record<string, any>;

const Carousel3D: React.FC<Carousel3DProps> = ({
  backgroundColor = "#f0f0f0",
  transparentBackground = false,
  durationInSeconds = 10,
  radius = 450,
  cardWidth = 350,
  cardHeight = 500,
  maxBlur = 4,
  perspective = 1000,
  rotationSpeed = 1.0,
  images = [
    "https://malloy.blob.core.windows.net/web/testing/nike1.avif",
    "https://malloy.blob.core.windows.net/web/testing/nike2.avif",
    "https://malloy.blob.core.windows.net/web/testing/nike3.avif",
  ],
}) => {
  useFontLoader(["Inter", "Playfair Display"]);

  const frame = useCurrentFrame();
  const { width, height, fps } = useVideoConfig();

  const bgColor = transparentBackground ? `${backgroundColor}00` : backgroundColor;

  // New rotation logic: Stop for 1 second, then rotate to next item
  const anglePerItem = (2 * Math.PI) / 3;
  const pauseFrames = fps; // Stop for exactly 1 second
  const moveFrames = Math.max(1, fps / rotationSpeed); // Transition duration based on speed
  const totalPeriod = pauseFrames + moveFrames;

  const currentCycle = Math.floor(frame / totalPeriod);
  const frameInCycle = frame % totalPeriod;

  const cycleRotation = interpolate(
    frameInCycle,
    [pauseFrames, totalPeriod],
    [0, anglePerItem],
    {
      extrapolateLeft: "clamp",
      extrapolateRight: "clamp",
    }
  );

  const globalRotation = -1 * (currentCycle * anglePerItem + cycleRotation);

  const items = useMemo(() => {
    // Ensure we have exactly 3 items for the carousel logic if fewer are provided
    const displayImages =
      images.length >= 3
        ? images.slice(0, 3)
        : [
            ...images,
            "https://picsum.photos/seed/fallback1/400/600",
            "https://picsum.photos/seed/fallback2/400/600",
            "https://picsum.photos/seed/fallback3/400/600",
          ].slice(0, 3);

    return displayImages.map((src, index) => {
      // 3 items spaced by 120 degrees (2 * PI / 3)
      const offsetAngle = (index * 2 * Math.PI) / 3;
      const currentAngle = globalRotation + offsetAngle;

      // Calculate position on the circle
      // sin for X, cos for Z (depth)
      const rawSin = Math.sin(currentAngle);
      const rawCos = Math.cos(currentAngle);

      // X position: 0 is center, radius * sin is offset
      const x = rawSin * (radius * 0.8); // 0.8 to keep it slightly contained

      // Z position determines scale, blur, and z-index
      // Cos ranges from -1 (back) to 1 (front)
      // We map this -1..1 range to our visual properties
      
      const normalizedDepth = (rawCos + 1) / 2; // 0 (back) to 1 (front)

      // Scale: 0.7 at back, 1.1 at front
      const scale = interpolate(rawCos, [-1, 1], [0.7, 1.1]);

      // Blur: 0 at front, maxBlur at back
      // Using a slightly sharper dropoff so only the very front is crystal clear
      const blur = interpolate(rawCos, [0.5, 1], [maxBlur, 0], {
        extrapolateLeft: "clamp",
        extrapolateRight: "clamp",
      });

      // Z-Index: Higher is closer
      const zIndex = Math.round(normalizedDepth * 100);

      // Opacity: Fade out the back slightly for better depth
      const opacity = interpolate(rawCos, [-1, -0.5, 1], [0.6, 0.8, 1]);

      return {
        id: index,
        src,
        x,
        scale,
        blur,
        zIndex,
        opacity,
        angle: currentAngle,
        isFront: rawCos > 0.9, // Flag if it's currently the "featured" item
      };
    });
  }, [globalRotation, images, radius, maxBlur]);

  return (
    <AbsoluteFill
      style={{
        backgroundColor: bgColor,
        fontFamily: "Inter",
        perspective: `${perspective}px`,
        overflow: "hidden",
      }}
    >
      {/* Central Container to center the carousel */}
      <div
        style={{
          position: "absolute",
          top: "50%",
          left: "50%",
          width: 0,
          height: 0,
          transformStyle: "preserve-3d",
        }}
      >
        {items.map((item) => (
          <div
            key={item.id}
            style={{
              position: "absolute",
              width: cardWidth,
              height: cardHeight,
              // Center the card on its coordinate
              left: -cardWidth / 2,
              top: -cardHeight / 2,
              transform: `translateX(${item.x}px) scale(${item.scale})`,
              zIndex: item.zIndex,
              filter: `blur(${item.blur}px)`,
              opacity: item.opacity,
              transition: "none", // Critical for frame-based animation
              willChange: "transform, filter, opacity",
              borderRadius: 20,
              boxShadow: item.isFront
                ? "0 20px 50px rgba(0,0,0,0.3)" // Strong shadow for front
                : "0 10px 20px rgba(0,0,0,0.1)", // Weak shadow for back
              backgroundColor: "white",
              display: "flex",
              flexDirection: "column",
              overflow: "hidden",
            }}
          >
            {/* Image Area */}
            <div
              style={{
                flex: 1,
                backgroundImage: `url(${item.src})`,
                backgroundSize: "cover",
                backgroundPosition: "center",
              }}
            />

            {/* Overlay for depth (darkens back cards) */}
            <div
              style={{
                position: "absolute",
                top: 0,
                left: 0,
                right: 0,
                bottom: 0,
                backgroundColor: "black",
                opacity: interpolate(item.scale, [0.7, 1.1], [0.3, 0]),
                pointerEvents: "none",
              }}
            />
          </div>
        ))}
      </div>
      
      {/* Decorative Floor Shadow */}
      <div
        style={{
            position: "absolute",
            top: "50%",
            left: "50%",
            width: radius * 2.5,
            height: 100,
            background: "radial-gradient(ellipse at center, rgba(0,0,0,0.15) 0%, rgba(0,0,0,0) 70%)",
            transform: `translate(-50%, ${cardHeight * 0.45}px) rotateX(80deg)`,
            zIndex: 0,
            pointerEvents: "none",
        }}
      />
    </AbsoluteFill>
  );
};

export default Carousel3D;